/**
 * CsvExportAction — scope/filter summary plus the "Export CSV" button
 * (DESIGN_SYSTEM.md: CSVExportAction).
 *
 * The CSV is generated by GET /exports/transactions.csv with exactly the same
 * filters as the transaction list shown on the page.  Pending, success and
 * failure (with retry) are all announced; a failure never clears the filters.
 */

import { secondaryButton } from '@/components/ui/styles'

interface CsvExportActionProps {
  summary: string[]
  onExport: () => void
  pending: boolean
  disabled?: boolean
  disabledReason?: string
  errorMessage?: string
  successFilename?: string
}

export default function CsvExportAction({
  summary,
  onExport,
  pending,
  disabled = false,
  disabledReason,
  errorMessage,
  successFilename,
}: CsvExportActionProps) {
  return (
    <section
      aria-labelledby="export-heading"
      className="space-y-3 rounded-card border border-border bg-surface p-4"
    >
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0">
          <h2 id="export-heading" className="text-base font-semibold text-text-primary">
            Export CSV
          </h2>
          <p className="mt-1 text-caption text-text-secondary">
            Downloads every matching transaction (not just this page) as a CSV file.
          </p>
        </div>
        <button
          type="button"
          className={secondaryButton}
          onClick={onExport}
          disabled={pending || disabled}
          aria-busy={pending}
        >
          {pending ? 'Exporting…' : 'Export CSV'}
        </button>
      </div>

      <ul aria-label="Export scope and filters" className="space-y-0.5 text-sm text-text-primary">
        {summary.map((line) => (
          <li key={line} className="break-words">
            {line}
          </li>
        ))}
      </ul>

      {disabled && disabledReason && (
        <p className="text-sm text-danger-text">{disabledReason}</p>
      )}

      <div aria-live="polite">
        {errorMessage && (
          <div
            role="alert"
            className="rounded-input border border-danger-text bg-danger-bg p-3 text-sm text-danger-text"
          >
            <p>{errorMessage}</p>
            <button
              type="button"
              className="mt-2 inline-flex min-h-touch items-center font-semibold underline focus:outline-none focus:ring-2 focus:ring-brand-700"
              onClick={onExport}
              disabled={pending}
            >
              Retry export
            </button>
          </div>
        )}
        {!errorMessage && successFilename && !pending && (
          <p className="text-sm text-text-secondary">
            Last export: <span className="font-medium text-text-primary">{successFilename}</span>
          </p>
        )}
      </div>
    </section>
  )
}
